@layer components {
  .article-preview {
    background-color: var(--shelf-article-preview-bgColor-surface);
    color: var(--shelf-article-preview-fgColor-default);
  }

  .article-preview-title {
    color: var(--shelf-article-preview-fgColor-title);
    font-size: var(--shelf-fontSize-lg);
    font-weight: var(--shelf-fontWeight-semibold);
    line-height: var(--shelf-lineHeight-tight);
  }

  .article-preview-excerpt {
    color: var(--shelf-article-preview-fgColor-body);
    font-size: var(--shelf-fontSize-md);
    font-weight: var(--shelf-fontWeight-regular);
    line-height: var(--shelf-lineHeight-normal);
  }
}
